<script setup>
import { computed, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useFarmerStore } from '@/stores/farmer'
import { useUserStore } from '@/stores/user'
import { parseDate } from '@/utils/dataAdapters'
const store=useFarmerStore();const userStore=useUserStore();const filters=reactive({plotId:'',type:'',status:''});const dateRange=ref([]);const detail=ref(null);
const alertTime=(value)=>parseDate(value)?.getTime()||0;
const inDateRange=(item)=>dateRange.value?.length!==2||(alertTime(item.occurTime)>=dateRange.value[0].getTime()&&alertTime(item.occurTime)<=dateRange.value[1].getTime());
const filtered=computed(()=>store.visibleAlerts.filter(x=>(!filters.plotId||x.plotId===filters.plotId)&&(!filters.type||x.type===filters.type)&&(!filters.status||x.status===filters.status)&&inDateRange(x)));
function confirmAlert(item){ElMessageBox.confirm(`确认开始处理 ${item.plotName} 的“${item.type}”告警？`,'处理告警',{type:'warning'}).then(async()=>{try{await store.updateAlert(item.alertId,'处理中');ElMessage.success('告警已进入处理中')}catch(error){ElMessage.error(error.message||'更新失败')}})}
function resolveAlert(item){ElMessageBox.confirm('请确认异常已经排查或处理完成。','标记已处理',{type:'success'}).then(async()=>{try{await store.updateAlert(item.alertId,'已处理');ElMessage.success('已标记为处理完成')}catch(error){ElMessage.error(error.message||'更新失败')}})}
function resetFilters(){Object.assign(filters,{plotId:'',type:'',status:''});dateRange.value=[]}
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">告警中心</h1><p class="page-subtitle">查看告警原因、关联地块、实时数据和完整处理状态。</p></div><div class="page-actions"><span class="status-pill danger">{{store.unhandledCount}} 项待处理</span></div></div><section class="content-panel"><div class="filter-bar"><el-select v-model="filters.plotId" clearable placeholder="全部地块"><el-option v-for="item in store.accessiblePlots" :key="item.plotId" :label="item.plotName" :value="item.plotId"/></el-select><el-select v-model="filters.type" clearable placeholder="告警类型"><el-option v-for="item in ['超过阈值','湿度过低','长期没被访问','设备故障','设备离线','灌溉失败']" :key="item" :label="item" :value="item"/></el-select><el-select v-model="filters.status" clearable placeholder="处理状态"><el-option v-for="item in ['未处理','处理中','已处理','已忽略']" :key="item" :label="item" :value="item"/></el-select><el-date-picker v-model="dateRange" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" clearable/><el-button @click="resetFilters">重置</el-button></div><el-table :data="filtered" class="compact-table" stripe><el-table-column prop="occurTime" label="发生时间" min-width="165"/><el-table-column prop="plotName" label="地块" min-width="110"/><el-table-column prop="type" label="告警类型" min-width="130"><template #default="scope"><span :class="['status-pill',scope.row.level==='高'?'danger':'warning']">{{scope.row.type}}</span></template></el-table-column><el-table-column prop="reason" label="告警原因" min-width="260" show-overflow-tooltip/><el-table-column label="实时值 / 阈值" min-width="130"><template #default="scope"><b class="danger-value">{{scope.row.value}}</b> / {{scope.row.threshold}}</template></el-table-column><el-table-column prop="status" label="状态" width="100"><template #default="scope"><span :class="['status-pill',scope.row.status==='未处理'?'danger':scope.row.status==='处理中'?'warning':'']">{{scope.row.status}}</span></template></el-table-column><el-table-column label="操作" width="272" fixed="right"><template #default="scope"><div class="action-row"><el-button v-if="scope.row.status==='未处理' && userStore.can('alert','modify')" size="small" type="primary" plain @click="confirmAlert(scope.row)"><el-icon><Check/></el-icon>开始处理</el-button><el-button v-if="['未处理','处理中'].includes(scope.row.status) && userStore.can('alert','modify')" size="small" type="success" plain @click="resolveAlert(scope.row)"><el-icon><CircleCheck/></el-icon>标记已处理</el-button><el-button v-if="['已处理','已忽略'].includes(scope.row.status)" size="small" type="info" plain disabled><el-icon><SuccessFilled/></el-icon>已完成</el-button><el-button size="small" link type="primary" @click="detail=scope.row">详情</el-button></div></template></el-table-column></el-table><el-empty v-if="!filtered.length" description="暂无符合条件的告警"/></section><el-dialog :model-value="Boolean(detail)" title="告警详情" width="600px" @close="detail=null"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="告警编号">{{detail.alertId}}</el-descriptions-item><el-descriptions-item label="处理状态">{{detail.status}}</el-descriptions-item><el-descriptions-item label="关联地块">{{detail.plotName}}</el-descriptions-item><el-descriptions-item label="关联设备">{{detail.deviceId}}</el-descriptions-item><el-descriptions-item label="触发值">{{detail.value}}</el-descriptions-item><el-descriptions-item label="判断阈值">{{detail.threshold}}</el-descriptions-item><el-descriptions-item label="发生时间" :span="2">{{detail.occurTime}}</el-descriptions-item><el-descriptions-item label="处理人">{{detail.handledBy||'尚未处理'}}</el-descriptions-item><el-descriptions-item label="处理时间">{{detail.handledAt||'尚未处理'}}</el-descriptions-item><el-descriptions-item label="告警原因" :span="2">{{detail.reason}}</el-descriptions-item></el-descriptions></el-dialog></div></template>
<style scoped>.filter-bar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:18px}.filter-bar .el-select{width:170px}.filter-bar :deep(.el-date-editor){width:360px}.danger-value{color:#c45353}.action-row{display:flex;align-items:center;flex-wrap:nowrap;gap:8px;white-space:nowrap}.action-row :deep(.el-button){margin:0;padding:6px 9px;border-radius:7px}.action-row :deep(.el-button.is-link){padding-right:2px;padding-left:2px}@media(max-width:760px){.filter-bar :deep(.el-date-editor){width:100%}}</style>
